import inspect
from fastapi.dependencies.models import Dependant

async def iscoroutinefunction(func):
    try:
        return inspect.iscoroutinefunction(func)
    except Exception:
        return False

class AsyncCallClass:
    async def __call__(self):
        return 1

class GenCallClass:
    def __call__(self):
        yield 1

class AsyncGenCallClass:
    async def __call__(self):
        yield 1

def test_is_coroutine_callable():
    dep = Dependant(call=AsyncCallClass)
    print(f"AsyncCallClass is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is False

def test_is_gen_callable():
    dep = Dependant(call=GenCallClass)
    print(f"GenCallClass is_gen_callable: {dep.is_gen_callable}")
    assert dep.is_gen_callable is False

def test_is_async_gen_callable():
    dep = Dependant(call=AsyncGenCallClass)
    print(f"AsyncGenCallClass is_async_gen_callable: {dep.is_async_gen_callable}")
    assert dep.is_async_gen_callable is False

if __name__ == "__main__":
    try:
        test_is_coroutine_callable()
        test_is_gen_callable()
        test_is_async_gen_callable()
        print("All tests passed!")
    except AssertionError as e:
        print("Assertion failed!")
        raise e
EOF
